def F(name,rx,mult=1,note=None,ex=None,pick='min'):
    s=MM(rx,ex=ex,minp=100,pick=pick,only=[o for o,r in lib.ORG.items() if r['meta']['title']==name])
    if not s: raise SystemExit(f'нет {name} {rx}')
    s=s[0]
    if mult!=1: s['v']*=mult
    if note: s['za_chto']+=f' ({note})'
    return s
